<script setup lang="ts">
/**
 * Table.Header: a column header, a `<th>`, with the sort control when the column sorts.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/table.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import { Icon } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/table.module.css'

export interface TableHeaderProps {
  numeric?: boolean
  sortable?: boolean
  /**
   * Controlled by the caller: Table shows the sort control, and DataTable sorts.
   */
  sortDirection?: 'asc' | 'desc'
}

defineOptions({ name: 'TableHeader', inheritAttrs: false })

withDefaults(defineProps<TableHeaderProps>(), { numeric: false, sortable: false })
const emit = defineEmits<{ sort: [] }>()
defineSlots<{ default?: (props: Record<string, never>) => unknown }>()
</script>

<template>
  <th
    :class="styles.header"
    scope="col"
    :data-sortable="sortable ? '' : undefined"
    :data-numeric="numeric ? '' : undefined"
    :aria-sort="
      sortDirection === 'asc' ? 'ascending' : sortDirection === 'desc' ? 'descending' : undefined
    "
  >
    <!-- sort -->
    <button v-if="sortable" :class="styles.sortButton" type="button" @click="emit('sort')">
      <slot />
      <span :class="styles.sortIcon" :data-active="sortDirection !== undefined ? '' : undefined">
        <Icon
          :name="
            sortDirection === 'asc' ? 'sort-asc' : sortDirection === 'desc' ? 'sort-desc' : 'sort'
          "
          size="sm"
        />
      </span>
    </button>
    <template v-else>
      <slot />
    </template>
  </th>
</template>
